                var criteria = splitLines[1].Split(',').Select(li => int.Parse(li)).ToList();
                var longerCriteria = new List<int>();
                for (int i = 0; i < 5; i++)
                {
                    longerCriteria.AddRange(criteria);
                }
                total += CalculatePermutations(longerLine, longerCriteria);
            }
            return total;
        }

        internal static int CalculatePermutations(string missingLine, List<int> criteria)
        {
            var permutations = new List<string>();
            GeneratePermutations(missingLine.ToCharArray(), 0, permutations);

            var validPerms = 0;

            foreach (string permutation in permutations)
            {
                var damaged = permutation.Split('.').Where(li => li != "").ToList();
                var counts = damaged.Select(li => li.Length).ToList();

                if (counts.SequenceEqual(criteria))
                    validPerms++;
            }

            return validPerms;
        }

        internal static void GeneratePermutations(char[] springs, int index, List<string> permutations)
        {
            if (index == springs.Length)
            {
                permutations.Add(new string(springs));
                return;
            }

            if (springs[index] == '?')
            {
                springs[index] = '.';
                GeneratePermutations(springs, index + 1, permutations);

                springs[index] = '#';
                GeneratePermutations(springs, index + 1, permutations);

                springs[index] = '?';
            }
            else
            {
                GeneratePermutations(springs, index + 1, permutations);
            }
        }
    }
}
